return $input.all().map((item) => {
  const e = item.json || {};
  const err = [];
  valider(e, ENVELOPPE, 'entrée', err);
  if (!err.length && SCHEMA.sans_contact === true && chaines([e.config, e.donnees], []).some((t) => COURRIEL.test(t) || TELEPHONE.test(t))) err.push('entrée : adresse e-mail ou téléphone interdits (aucune donnée personnelle dans ce gabarit)');
  if (err.length) {
    const cle = typeof e.cle_idempotence === 'string' && /^[A-Za-z0-9_:@.#-]{1,80}$/.test(e.cle_idempotence) ? e.cle_idempotence : '';
    return { json: { conforme: false, enveloppe: { contrat: CONTRAT, simulation: true, cle_idempotence: cle }, erreurs: err.slice(0, 20) } };
  }
  return { json: { conforme: true, enveloppe: e, erreurs: [] } };
});

// lib-trier-demande (036-001 ; C10 « règles d'abord » ; A13) : chaque demande reçoit UNE classe, dans cet ordre (exclusives, fiche triage) :
// spam (piège rempli, 3 liens ou plus, vocabulaire de démarchage) > urgence (urgence déclarée ou sujet d'urgence) > client_existant > curieux
// > peut_attendre. L'escalade est lue À PART, comme le pilote la lit (sujetEscalade) : un sujet d'escalade renvoie toujours à l'artisan.
// Aucun modèle, aucun montant ; le texte reçu est déjà masqué (coordonnées) par le chef.
// ─── Copie figée de lib/pilote/regles.ts (MOTS_ESCALADE_TOUJOURS, MOTS_ESCALADE_ENTIERS et motifs de sujetEscalade), comparée au code par scripts/cerveau-accueil-n8n-qa.mjs ───
const COPIE = {"MOTS_ESCALADE_TOUJOURS":["litige","litigieux","sinistre","avocat","menace","mise en demeure","en demeure","plainte","tribunal","tribunaux","huissier","contentieux","conteste","contestation","arnaque","escroquerie","escroc","urgence","fuite","dégât des eaux","dégâts des eaux","dégât d’eau","dégâts d’eau","inondation","inondé","assurance","justice","prud’hom","juridique","médiateur","conciliat","dgccrf","gendarme","préjudice","indemni","dédommag","réclamation","lettre recommandée","recommandé avec","en recommandé","accusé de réception","vice caché","vices cachés","opposition","malfaçon","décennale","expert","dégât","incendie","brûl","blessé","blessure","électrocut","monoxyde","intoxi","effondr","écroul","infiltr","court-circuit","court circuit","danger","eau partout","est tombé","est tombée","sont tombés","une chute","fait une chute","paierai pas","payerai pas","réglerai pas","paie pas","paye pas","pas payer cette","pas payer la","pas payer tant","refuse de payer","refuse de régler","rembours","avis négatif","mauvais avis","mauvaise pub","assureur","menaç","voleur","poursuiv","vous attaquer","paierai rien","payerai rien","pas un centime","bloque le paiement","retiens le solde","retenir le solde","une étoile","explos","étincel","ça fume","pris une décharge","décharge électrique","s’est coupé","s’est blessé","signalement","réclame","remise en état","conflit","dénonce","fui","fuy","perd de l’eau","perdent de l’eau","perte d’eau","urgen","urgemment","goutte","suinte","déborde","sous l’eau","de l’eau par terre","plus de chauffage","plus d’eau chaude","au plus vite","pressant","entendre parler de moi","retiens le paiement","rendez-moi mon argent","une honte","avis sur google","plombs ont sauté","pris feu","court-jus","coule du","ça coule","goutte du","escroqu","plaindre","plains","dommages et","consommateur","bâcl","mal fait","fraude","disjoncteur saute","ça disjoncte","disjoncte sans","refui","refuy","humidit","humide","eau coule","coule le long","ruissel","s’échapp","s’écoul","eau qui sort","eau sort","eau se perd","de l’eau sous","lâche de l’eau","crache de l’eau","pisse de l’eau","se vide tout seul","perd du liquide","perte de liquide","c’est pressé","est très pressé","suis pressé","odeur"],"MOTS_ESCALADE_ENTIERS":["gaz","procès","police","accident","accidents","pompiers","juge","ufc","vol","samu","urssaf"],"FAUSSE_URGENCE":{"source":" (?:pas d|sans|aucune|rien d) urgen[a-z]*| pas urgent[a-z]*| (?:sans|aucun|pas de) degats?| une chute de (?:neige|pluie|grele|feuilles)","flags":"g"},"PERTE_D_EAU":{"source":" (?:perd[a-z]*|pert|pertes?)(?: (?!chauffe )[a-z0-9]+){0,5}? (?:d |de l |de |l |d l )?d?l?eaux? ","flags":""},"APPAREIL_PERD":{"source":" (?:chauffe eau|ballon|cumulus|radiateur|radiateurs|robinet|chaudiere|tuyau|tuyaux|joint|wc|evier|lavabo|siphon|vanne) (?:perd|perdent|perdait|perdaient|a perdu|ont perdu)(?= $| pouvez| pourriez| depuis| encore| toujours| beaucoup| un peu| pas mal| partout| de partout| par terre| par le| sous| a nouveau| merci)","flags":""},"NOMS_NEUTRES":{"source":"\\b(?:chaudieres?|cuisinieres?|plaques?(?:[^a-z0-9]+de[^a-z0-9]+cuisson)?)[^a-z0-9]+(?:(?:a|au)[^a-z0-9]+)?gaz\\b|\\bbruleurs?\\b|\\battestations?[^a-z0-9]+(?:d[^a-z0-9]+)?(?:assurances?[^a-z0-9]*)?(?:decennale|rc pro|responsabilite civile)?","flags":"g"}};
// ─── fin de la copie figée ───
const sansAccents = (s) => String(s == null ? '' : s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const enMots = (s) => ' ' + sansAccents(s).replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const R = (n) => new RegExp(COPIE[n].source, COPIE[n].flags);
const FAUSSE_URGENCE = R('FAUSSE_URGENCE'), PERTE_D_EAU = R('PERTE_D_EAU'), APPAREIL_PERD = R('APPAREIL_PERD'), NOMS_NEUTRES = R('NOMS_NEUTRES');
const TOUJOURS = COPIE.MOTS_ESCALADE_TOUJOURS.map((m) => [m, enMots(m).trim()]);
const ENTIERS = COPIE.MOTS_ESCALADE_ENTIERS.map((m) => [m, enMots(m).trim()]);
function sujetEscalade(messages, motsArtisan) {
  const artisan = (Array.isArray(motsArtisan) ? motsArtisan : []).filter((m) => typeof m === 'string').map((m) => [m, sansAccents(m).trim()]).filter((x) => x[1] !== '');
  for (const brut of messages) {
    if (typeof brut !== 'string' || !brut.trim()) continue;
    const mots = enMots(brut).replace(NOMS_NEUTRES, ' ').replace(FAUSSE_URGENCE, ' ').replace(/ {2,}/g, ' ');
    for (const [m, k] of TOUJOURS) if (k && mots.includes(' ' + k)) return m;
    for (const [m, k] of ENTIERS) if (k && mots.includes(' ' + k + ' ')) return m;
    if (PERTE_D_EAU.test(mots)) return 'perte d’eau';
    if (APPAREIL_PERD.test(mots)) return 'perte d’eau';
    if (mots.includes(' ca sent ')) return 'ça sent';
    const texte = sansAccents(brut).replace(NOMS_NEUTRES, ' ');
    for (const [m, k] of artisan) if (texte.includes(k)) return m;
  }
  return null;
}
const SPAM = / (casino|crypto|bitcoin|viagra|backlinks?|referencement naturel|seo|pret rapide|gagnez|cliquez ici|offre exclusive) /;
const CURIEUX = / (simple question|juste savoir|par curiosite|renseignement|a titre indicatif|ordre de grandeur|combien coute|combien ca coute) /;
const URGENT = /urgen|press|vite|fui|fuy|fuite|inond|eau|gaz|feu|incendi|danger|electrocut|monoxyde|odeur|ca sent|explos|etincel|chauffage/;
return $input.all().map((item) => {
  const j = item.json;
  try {
    const e = j.enveloppe, d = e.donnees, t = d.texte || '';
    const mot = sujetEscalade([t], e.config.mots_escalade_artisan);
    const m = enMots(t), motifs = [];
    let classe = 'peut_attendre';
    if (d.honeypot === true) { classe = 'spam'; motifs.push('piege_rempli'); }
    else if (d.liens >= 3) { classe = 'spam'; motifs.push('liens_multiples'); }
    else if (SPAM.test(m)) { classe = 'spam'; motifs.push('vocabulaire_demarchage'); }
    else if (d.urgence_declaree === true || (mot && URGENT.test(sansAccents(mot)))) { classe = 'urgence'; motifs.push(d.urgence_declaree === true ? 'urgence_declaree' : 'sujet_urgent'); }
    else if (d.client_existant === true) { classe = 'client_existant'; motifs.push('contact_deja_client'); }
    else if (CURIEUX.test(m) || !t.trim()) { classe = 'curieux'; motifs.push(t.trim() ? 'simple_renseignement' : 'message_vide'); }
    else motifs.push('demande_ordinaire');
    if (mot) motifs.push('escalade');
    const resultat = { demande_id: d.demande_id, classe: classe, escalade: !!mot, mot: mot, motifs: motifs };
    return { json: { ...j, statut: 'ok', resultat: resultat, effets_prevus: [],
      journal: [{ evenement: 'tri', agent: 'lib-trier-demande', objet_ref: d.demande_id, decision: ('classe ' + classe + (mot ? ', escalade (« ' + mot + ' »)' : '')).slice(0, 200), simulation: e.simulation }] } };
  } catch (err) {
    return { json: { ...j, statut: 'erreur', resultat: null, effets_prevus: [], erreurs: ['tri : ' + String((err && err.message) || err).slice(0, 120)] } };
  }
});

// Contrat de sortie de lib-trier-demande@1 : le seul nœud final ; effets_faits reste vide en simulation.
const CONTRAT = 'lib-trier-demande@1';
// ─── Gabarit « Contrat de sortie » 035-003 : au-dessus, CONTRAT seulement ; en dessous, le corps commun (empreinte tenue par le juge) ───
const STATUTS = ['ok', 'rien_a_faire', 'rejete', 'refuse', 'erreur'];
const liste = (x) => Array.isArray(x) ? x : [];
return $input.all().map((item) => {
  const j = item.json || {};
  const e = j.enveloppe && typeof j.enveloppe === 'object' ? j.enveloppe : {};
  const simulation = e.simulation !== false;
  const rejete = j.conforme === false;
  const statut = rejete ? 'rejete' : STATUTS.includes(j.statut) ? j.statut : 'erreur';
  const journal = liste(j.journal).slice(0, 200);
  if (rejete) journal.push({ evenement: 'contrat_rejete', agent: CONTRAT, objet_ref: null, decision: 'entrée hors contrat : aucun effet', simulation: simulation });
  return { json: {
    'contrat': CONTRAT,
    'statut': statut,
    'cle_idempotence': typeof e.cle_idempotence === 'string' ? e.cle_idempotence.slice(0, 80) : '',
    'simulation': simulation,
    'resultat': rejete || statut === 'erreur' ? null : (j.resultat && typeof j.resultat === 'object' ? j.resultat : null),
    'effets_prevus': rejete ? [] : liste(j.effets_prevus),
    'effets_faits': simulation || rejete ? [] : liste(j.effets_faits),
    'journal': journal,
    'erreurs': liste(j.erreurs).map(String).slice(0, 20),
  } };
});
